    run_test(
        &format!(r#"{left}r#'abcde""fghi"''''jkl'#{right}"#),
        r#"abcde""fghi"''''jkl"#,
    )?;
    run_test(
        &format!(r#"{left}r##'abcde""fghi"''''#jkl'##{right}"#),
        r#"abcde""fghi"''''#jkl"#,
    )?;
    run_test(
        &format!(r#"{left}r###'abcde""fghi"'''##'#jkl'###{right}"#),
        r#"abcde""fghi"'''##'#jkl"#,
    )?;
    run_test(&format!("{left}r#''#{right}"), "")?;
    run_test(
        &format!(r#"{left}r#'a string with sharp inside # and ends with #'#{right}"#),
        "a string with sharp inside # and ends with #",
    )
}

